    12→        None = 0,
    13→        IncludeSignature = 1,
    14→        Packed = 2,
    15→        All = 3
    16→    }
    17→
    18→    public class AbiEncoder : IAbiEncoder
    19→    {
    20→        public static readonly AbiEncoder Instance = new();
    21→
    22→        public byte[] Encode(AbiEncodingStyle encodingStyle, AbiSignature signature, params object[] arguments)
    23→        {
    24→            bool packed = (encodingStyle & AbiEncodingStyle.Packed) == AbiEncodingStyle.Packed;
    25→            bool includeSig = encodingStyle == AbiEncodingStyle.IncludeSignature;
    26→
    27→            if (arguments.Length != signature.Types.Length)
    28→            {
    29→                throw new AbiException($"Insufficient parameters for {signature.Name}. Expected {signature.Types.Length} arguments but got {arguments.Length}");
    30→            }
    31→
    32→            byte[][] encodedArguments = AbiType.EncodeSequence(signature.Types.Length, signature.Types, arguments, packed, includeSig ? 1 : 0);
    33→
    34→            if (includeSig)
    35→            {
    36→                encodedArguments[0] = signature.Address;
    37→            }
    38→
    39→            return Bytes.Concat(encodedArguments);
    40→        }
    41→
    42→        public object[] Decode(AbiEncodingStyle encodingStyle, AbiSignature signature, byte[] data)
    43→        {
    44→            bool packed = (encodingStyle & AbiEncodingStyle.Packed) == AbiEncodingStyle.Packed;
    45→            bool includeSig = encodingStyle == AbiEncodingStyle.IncludeSignature;
    46→            int sigOffset = includeSig ? 4 : 0;
    47→            if (includeSig)
    48→            {
    49→                if (!Bytes.AreEqual(AbiSignature.GetAddress(data), signature.Address))
    50→                {
    51→                    throw new AbiException($"Signature in encoded ABI data is not consistent with {signature}");
    52→                }
    53→            }
    54→
    55→            (object[] arguments, int position) = AbiType.DecodeSequence(signature.Types.Length, signature.Types, data, packed, sigOffset);
    56→
    57→            if (position != data.Length)
    58→            {
    59→                throw new AbiException($"Unexpected data at position {position}");
    60→            }
    61→
    62→            return arguments;
    63→        }
    64→    }
    65→}
